package com.aadil.jobtracker.security;import io.jsonwebtoken.Jwts;import io.jsonwebtoken.io.Encoders;import javax.crypto.SecretKey;public class SecretKeyGenerator {    public static void main(String[] args) {        SecretKey secretKey = Jwts.SIG.HS256.key().build();        String encodedKey = Encoders.BASE64.encode(secretKey.getEncoded());        System.out.println(encodedKey);    }}